b+='<text x="360" y="28" text-anchor="middle" font-size="18" font-weight="bold">Shape can decide: float or sink?</text>'
# foil spread (floats)
b+='<rect x="90" y="104" width="110" height="8" fill="#b9bcc2" stroke="#666"/><text x="145" y="150" text-anchor="middle" font-size="13">Foil spread out</text><text x="145" y="168" text-anchor="middle" font-size="13" font-weight="bold">FLOATS</text>'
