b+='<path d="M270 90 L290 112 L340 112 L360 90" fill="#b9bcc2" stroke="#666" stroke-width="2"/><text x="315" y="150" text-anchor="middle" font-size="13">Foil as a cup</text><text x="315" y="168" text-anchor="middle" font-size="13" font-weight="bold">FLOATS</text>'
